/*
 * A261654  Lead almost-Pythagorean triples generated by primitive Pythagorean
 *          triples of the form (2i-1, 2i^2-2i, 2i^2-2i+1), i >= 2.
 * https://oeis.org/A261654
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, tabf
 * Formula:   let i = 2 + floor((n-1)/3). a(n) = 2*i if n mod 3 == 1 a(n) =
 *            2*i*i - 1 if n mod 3 == 2 a(n) = 2*i*i if n mod 3 == 0
 * Range:     u8 n <= 31, u16 n <= 48, u32 n <= 48, u64 n <= 48, u128 n <= 48,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    if (n == 0) return 0;
    idx_t idx = n - 1;
    seq_t i = (seq_t)(2 + idx / 3);
    switch (idx % 3) {
        case 0: /* n mod 3 == 1 : first component */
            return i << 1;                      /* 2*i */
        case 1: /* n mod 3 == 2 : second component */
        {
            seq_t t = i * i;
            return (t << 1) - 1;                 /* 2*i*i - 1 */
        }
        case 2: /* n mod 3 == 0 : third component */
        {
            seq_t t = i * i;
            return t << 1;                       /* 2*i*i */
        }
    }
    return 0;  /* unreachable */
}
